async function frameButtons(fid) {
  const f = await figma.getNodeByIdAsync(fid);
  const acts = f.children.find(c => c.name === 'section-actions');
  const btns = acts.findAll(n => n.type === 'INSTANCE');
  const back = btns.find(b => b.findOne(t => t.type === 'TEXT' && t.characters === 'Back'));
  const next = btns.find(b => b.findOne(t => t.type === 'TEXT' && (t.characters === 'Next' || t.characters === 'Pay')));
  return {back, next};
}
