async function checkFill(id, name) {
  const n = await figma.getNodeByIdAsync(id);
  const isImg = n.fills && n.fills[0] && n.fills[0].type === 'IMAGE';
  return name + ':' + (isImg ? 'IMG' : (n.fills ? n.fills[0].type : 'none'));
}
